import{_ as o,o as a,c as t,a2 as d}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Package Extraction","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-record-view/package-extraction.md","filePath":"dynamic-record-view/package-extraction.md"}'),c={name:"dynamic-record-view/package-extraction.md"};function r(i,e,n,s,l,p){return a(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="package-extraction" tabindex="-1">Package Extraction <a class="header-anchor" href="#package-extraction" aria-label="Permalink to &quot;Package Extraction&quot;">​</a></h1><p>Status: <strong>Not attempted — assessment only.</strong> No code was moved; this documents what it would take if the engine were ever pulled out of <code>app/Support/DynamicRecordView</code> into a standalone Composer package.</p><h2 id="already-package-friendly" tabindex="-1">Already package-friendly <a class="header-anchor" href="#already-package-friendly" aria-label="Permalink to &quot;Already package-friendly&quot;">​</a></h2><ul><li><strong>Core</strong> (<code>app/Support/DynamicRecordView/Core/</code>) is architecture-tested (<code>tests/Feature/DynamicRecordView/ArchitectureTest.php</code>) to import nothing from <code>Modules\\*</code>, Livewire, or Blade — it&#39;s already framework-agnostic PHP plus a hard dependency on Eloquent (<code>Builder</code>, <code>Model</code>, <code>Relation</code>).</li><li><strong>Resolution</strong> (<code>app/Support/DynamicRecordView/Resolution/</code>) depends on Core plus Laravel&#39;s <code>DB</code> facade and HTTP exception — no <code>Modules\\*</code> coupling either.</li></ul><h2 id="what-would-need-to-change" tabindex="-1">What would need to change <a class="header-anchor" href="#what-would-need-to-change" aria-label="Permalink to &quot;What would need to change&quot;">​</a></h2><ol><li><strong>Namespace</strong> — <code>App\\Support\\DynamicRecordView\\*</code> would become the package&#39;s own vendor namespace; every consuming <code>Modules\\*</code> class updates its <code>use</code> statements.</li><li><strong>Service provider</strong> — <code>RecordResolver</code>/<code>RecordReferenceRegistry</code>/ <code>RecordViewRegistry</code>&#39;s <code>$this-&gt;app-&gt;scoped(...)</code> bindings currently live in <code>App\\Providers\\AppServiceProvider::register()</code>; a package needs its own <code>PackageServiceProvider</code> registering these, auto-discovered via <code>composer.json</code>&#39;s <code>extra.laravel.providers</code>.</li><li><strong>Livewire component registration</strong> — <code>App\\Livewire\\DynamicRecordView\\*</code> components are currently autoloaded by convention; a package needs explicit <code>Livewire::component()</code> registration in its provider (Livewire doesn&#39;t autodiscover a package&#39;s <code>Livewire\\*</code> namespace the way an app does).</li><li><strong>Blade views</strong> — <code>resources/views/components/dynamic-record-view/</code> and <code>resources/views/livewire/dynamic-record-view/</code> would move under the package&#39;s own <code>resources/views</code>, published/loaded via <code>loadViewsFrom()</code>/<code>publishes()</code>, with the <code>x-dynamic-record-view.*</code> component namespace registered via <code>Blade::componentNamespace()</code>.</li><li><strong>Flux UI dependency</strong> — the views use <code>&lt;flux:*&gt;</code> components directly; the package would need to declare <code>livewire/flux-ui</code> as a dependency (or make the UI layer swappable, which is a larger redesign) rather than assuming the host app has it installed, as this codebase does.</li><li><strong>Migrations</strong> — none currently belong to this engine directly (it reads existing application tables/relations), so no migration-publishing concern exists today. If a future feature needed its own table (e.g. persisted view preferences specific to record views, distinct from <code>App\\Models\\TableView</code>/<code>UserTablePreference</code> which already exist and are reused as-is), it would need <code>publishes()</code>-style migration publishing.</li><li><strong>Tests</strong> — <code>tests/Feature/DynamicRecordView/*</code> currently exercise real <code>Modules\\General\\*</code> models/routes (<code>SubModule</code>, <code>Application</code>, <code>Country</code>, <code>City</code>) as its canonical examples. A package&#39;s own test suite would need fixture models/migrations instead, since it can&#39;t depend on this app&#39;s modules.</li></ol><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p>Core + Resolution are close to package-ready today (clean dependency boundary, already tested for it). Livewire components, Blade views, and the Flux UI coupling are the real work — this is a multi-day effort, not attempted in this pass, and not currently planned.</p>',8)])])}const h=o(c,[["render",r]]);export{g as __pageData,h as default};
